    @timeout_decorator.timeout(60)
    def test_44_post_on_revoke_vulnerableToXSS(self):
        
        headers = {}
        headers["content-type"] = "application/json"
        body = " { " + \
            " \"email\" : \"victim@example.com\", " + \
            " \"password\" : \"V1ctim-Bamf-Thesis-2026\" " + \
            " } "
        res_victim_example_com = requests \
                .post("http://localhost:8211/login", 
                    headers=headers, data=body, allow_redirects=False, verify=False)
        token_victim_example_com =  res_victim_example_com.json()["token"]
        
        auth_victim_example_com = "Bearer " + token_victim_example_com
        
        # Fault201. Cross-Site Scripting (XSS).
        headers = {}
        headers["Authorization"] = auth_victim_example_com # victim@example.com
        headers["content-type"] = "application/json"
        body = {}
        body = " { " + \
            " \"fingerprint\" : \"<img src=x onerror=alert('XSS')>\", " + \
            " \"reason\" : \"<img src=x onerror=alert('XSS')>\" " + \
            " } "
        headers['Accept'] = "application/json"
        res_0 = requests \
                .post(self.baseUrlOfSut + "/api/v1/certificates/revoke",
                    headers=headers, data=body, timeout=EM_HTTP_TIMEOUT_S, verify=False)
        
        assert res_0.status_code == 200
        assert "application/json" in res_0.headers["content-type"]
        assert res_0.json()["fingerprint"] == "<imgsrc=xonerror=alert('xss')>"
        assert res_0.json()["revoked_at"] == "2026-09-30T04:13:40.183791Z"
        assert res_0.json()["reason"] == "<img src=x onerror=alert('XSS')>"
        assert res_0.json()["revoked_by"] == "victim@example.com"
        assert res_0.json()["subject_cn"] is None
    
    
